  static AdaptiveCapture(){Application.ApplicationExit+=(s,e)=>DisposeFonts();}
  public static Font CachedFont(float size,bool emphasis){float selected=fontSizes[0];double delta=double.MaxValue;foreach(float candidate in fontSizes){double next=Math.Abs(candidate-size);if(next<delta){delta=next;selected=candidate;}}string key=selected.ToString(System.Globalization.CultureInfo.InvariantCulture)+(emphasis?"b":"r");lock(fontGate){Font value;if(!fonts.TryGetValue(key,out value)){value=new Font("Segoe UI",selected,emphasis?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Point);fonts.Add(key,value);}return value;}}
  public static void DisposeFonts(){lock(fontGate){foreach(var font in fonts.Values)font.Dispose();fonts.Clear();}}
  static Size TargetSize(int width,int height){double factor=Math.Min(1.0,MaximumDimension/(double)Math.Max(width,height));return new Size(Math.Max(1,(int)Math.Round(width*factor)),Math.Max(1,(int)Math.Round(height*factor)));}
  sealed class Context {
   readonly object app,channel;readonly FieldInfo active,generation,lastInput;readonly MethodInfo state,send,ui,setStatus;readonly int epoch;
   public Context(object a,object c,int e){app=a;channel=c;epoch=e;var type=a.GetType();var flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;active=type.GetField("active",flags);generation=type.GetField("generation",flags);lastInput=type.GetField("lastRemoteInput",flags);state=type.GetMethod("State",flags);ui=type.GetMethod("UI",flags);setStatus=type.GetMethod("SetStatusText",flags);send=c.GetType().GetMethod("Send",flags);if(active==null||generation==null||send==null)throw new InvalidOperationException("Capture binding unavailable.");}
