   public bool InputActive(){if(lastInput==null)return false;try{double elapsed=(DateTime.UtcNow-(DateTime)lastInput.GetValue(app)).TotalMilliseconds;return elapsed>=0&&elapsed<1500;}catch{return false;}}
   public void Notify(string text){try{if(!Alive())return;if(ui!=null&&setStatus!=null){Action update=()=>{try{if(Alive())setStatus.Invoke(app,new object[]{text});}catch{}};ui.Invoke(app,new object[]{update});}else if(state!=null)state.Invoke(app,new object[]{text});}catch{}}
   public void Send(byte[] bytes){try{send.Invoke(channel,new object[]{bytes});}catch(TargetInvocationException error){throw error.InnerException??error;}}
   public void Pause(int milliseconds,bool wakeOnInput){var clock=Stopwatch.StartNew();while(clock.ElapsedMilliseconds<milliseconds&&Alive()){if(wakeOnInput&&InputActive())break;Thread.Sleep((int)Math.Max(1,Math.Min(15,milliseconds-clock.ElapsedMilliseconds)));}}
  }
  sealed class Buffer:IDisposable {
   public readonly Bitmap Image;public readonly Graphics Graphics;readonly int[] pixels,last;readonly MemoryStream encoded=new MemoryStream(262144);readonly EncoderParameters parameters=new EncoderParameters(1);readonly ImageCodecInfo jpeg;bool sent;ulong previousHash;
   public Buffer(Size size){Image=new Bitmap(size.Width,size.Height,PixelFormat.Format32bppRgb);Graphics=Graphics.FromImage(Image);pixels=new int[size.Width*size.Height];last=new int[pixels.Length];foreach(var codec in ImageCodecInfo.GetImageEncoders())if(codec.FormatID==ImageFormat.Jpeg.Guid){jpeg=codec;break;}if(jpeg==null)throw new InvalidOperationException("JPEG encoder not available.");parameters.Param[0]=new EncoderParameter(System.Drawing.Imaging.Encoder.Quality,(long)JpegQuality);}
