  }
  [DllImport("user32.dll",SetLastError=true)]static extern IntPtr GetDC(IntPtr window);
  [DllImport("user32.dll")]static extern int ReleaseDC(IntPtr window,IntPtr dc);
  [DllImport("gdi32.dll",SetLastError=true)]static extern bool StretchBlt(IntPtr target,int x,int y,int width,int height,IntPtr source,int sx,int sy,int sourceWidth,int sourceHeight,uint raster);
  [DllImport("gdi32.dll")]static extern int SetStretchBltMode(IntPtr dc,int mode);
  [DllImport("gdi32.dll")]static extern bool SetBrushOrgEx(IntPtr dc,int x,int y,IntPtr point);
  static void ScreenInto(Buffer target,Rectangle bounds){IntPtr source=IntPtr.Zero,destination=IntPtr.Zero;try{source=GetDC(IntPtr.Zero);if(source==IntPtr.Zero)throw new Win32Exception(Marshal.GetLastWin32Error(),"Ekran DC alınamadı.");destination=target.Graphics.GetHdc();SetStretchBltMode(destination,4);SetBrushOrgEx(destination,0,0,IntPtr.Zero);if(!StretchBlt(destination,0,0,target.Image.Width,target.Image.Height,source,bounds.Left,bounds.Top,bounds.Width,bounds.Height,0x40cc0020))throw new Win32Exception(Marshal.GetLastWin32Error(),"Ekran yakalama geçici olarak kullanılamıyor.");}finally{if(destination!=IntPtr.Zero)target.Graphics.ReleaseHdc(destination);if(source!=IntPtr.Zero)ReleaseDC(IntPtr.Zero,source);}}
  public static void Run(object app,object channel,int generation){Context context;try{context=new Context(app,channel,generation);}catch{return;}Buffer buffer=null;var age=Stopwatch.StartNew();long lastSent=-KeyframeIntervalMs;int failures=0;try{while(context.Alive()){var cycle=Stopwatch.StartNew();bool changed=false;try{var display=Screen.PrimaryScreen;if(display==null)throw new Win32Exception("Birincil ekran bulunamadı.");Rectangle bounds=display.Bounds;if(bounds.Width<1||bounds.Height<1)throw new Win32Exception("Ekran boyutu geçersiz.");Size target=TargetSize(bounds.Width,bounds.Height);if(buffer==null||buffer.Image.Size!=target){if(buffer!=null)buffer.Dispose();buffer=new Buffer(target);lastSent=-KeyframeIntervalMs;}ScreenInto(buffer,bounds);Interlocked.Increment(ref CapturedFrames);ulong hash=buffer.ReadHash();changed=buffer.Changed(hash);bool keyframe=age.ElapsedMilliseconds-lastSent>=KeyframeIntervalMs;if((changed||keyframe)&&Transport.CanEncodeScreen(channel)){byte[] bytes=buffer.Encode();try{context.Send(bytes);}catch(Exception error){context.Notify("Ekran aktarımı durdu: "+error.Message);return;}buffer.Remember(hash);lastSent=age.ElapsedMilliseconds;Interlocked.Increment(ref EncodedFrames);Interlocked.Add(ref QueuedBytes,bytes.Length);}else Interlocked.Increment(ref SkippedFrames);if(failures>0)context.Notify("Bağlandı. Ekran aktarımı yeniden başladı.");failures=0;}
   catch(Win32Exception error){failures++;Interlocked.Increment(ref CaptureFailures);if(failures==1||failures%10==0)context.Notify("Ekran geçici olarak alınamıyor; yeniden deneniyor. "+error.Message);context.Pause(Math.Min(2000,250*failures),false);continue;}
   catch(ExternalException error){failures++;Interlocked.Increment(ref CaptureFailures);if(failures==1||failures%10==0)context.Notify("Ekran hazırlanıyor; yeniden deneniyor. "+error.Message);context.Pause(Math.Min(2000,250*failures),false);continue;}
   catch(Exception error){context.Notify("Ekran aktarımı durdu: "+error.Message);return;}
   int interval=context.InputActive()?ActiveIntervalMs:changed?ChangedIntervalMs:IdleIntervalMs;context.Pause((int)Math.Max(10,interval-cycle.ElapsedMilliseconds),interval==IdleIntervalMs);
  }}finally{if(buffer!=null)buffer.Dispose();}}
  static void SyntheticInto(Buffer target,Bitmap source,Graphics sourceGraphics){sourceGraphics.Flush(System.Drawing.Drawing2D.FlushIntention.Sync);target.Graphics.DrawImage(source,new Rectangle(0,0,target.Image.Width,target.Image.Height),new Rectangle(0,0,source.Width,source.Height),GraphicsUnit.Pixel);target.Graphics.Flush(System.Drawing.Drawing2D.FlushIntention.Sync);}
  public static void Test(){using(var a=new Buffer(new Size(64,40))){a.Graphics.Clear(Color.White);ulong first=a.ReadHash();if(!a.Changed(first))throw new Exception("First frame not changed");a.Remember(first);if(a.Changed(a.ReadHash()))throw new Exception("Identical frame not suppressed");a.Graphics.FillRectangle(Brushes.Red,1,1,1,1);if(!a.Changed(a.ReadHash()))throw new Exception("Single-pixel change missed");byte[] bytes=a.Encode();if(bytes.Length<4||bytes[0]!=1||bytes[1]!=0xff||bytes[2]!=0xd8)throw new Exception("JPEG frame envelope invalid");}Font f=CachedFont(16,false);for(int i=0;i<10000;i++)if(!object.ReferenceEquals(f,CachedFont(16,false)))throw new Exception("Font cache unstable");DisposeFonts();if(TargetSize(3840,2160)!=new Size(1280,720)||TargetSize(1080,3840).Height>1280)throw new Exception("Capture bounds incorrect");}
  public static string Benchmark(int width,int height,int frames){if(width<64||height<64||width>8192||height>8192||frames<2||frames>300)throw new ArgumentOutOfRangeException();var report=new StringBuilder("scenario,mode,width,height,frames,encoded,elapsed_ms,cpu_ms,jpeg_bytes,private_after_mib,working_set_after_mib,gen0,gen1,gen2\n");foreach(bool moving in new[]{false,true})foreach(bool adaptive in new[]{false,true}){using(var source=new Bitmap(width,height,PixelFormat.Format32bppRgb))using(var graphics=Graphics.FromImage(source))using(var font=new Font("Segoe UI",24)){graphics.Clear(Color.FromArgb(22,29,40));graphics.DrawString("Synthetic MR Daktilo benchmark - no desktop pixels",font,Brushes.White,25,25);for(int y=130;y<height;y+=80)for(int x=30;x<width;x+=180)graphics.FillRectangle(((x+y)/10)%2==0?Brushes.SlateGray:Brushes.DarkSlateGray,x,y,130,40);Size target=TargetSize(width,height);Buffer reusable=adaptive?new Buffer(target):null;GC.Collect();GC.WaitForPendingFinalizers();var process=Process.GetCurrentProcess();TimeSpan cpu=process.TotalProcessorTime;int g0=GC.CollectionCount(0),g1=GC.CollectionCount(1),g2=GC.CollectionCount(2),encoded=0;long bytes=0;var clock=Stopwatch.StartNew();for(int i=0;i<frames;i++){if(moving)graphics.FillRectangle(i%2==0?Brushes.Red:Brushes.Green,50,100,55,25);if(adaptive){SyntheticInto(reusable,source,graphics);ulong hash=reusable.ReadHash();if(reusable.Changed(hash)){bytes+=reusable.Encode().Length;reusable.Remember(hash);encoded++;}}else{using(var full=new Bitmap(width,height))using(var fullGraphics=Graphics.FromImage(full)){fullGraphics.DrawImageUnscaled(source,0,0);using(var scaled=new Bitmap(full,target))using(var memory=new MemoryStream())using(var parameters=new EncoderParameters(1)){parameters.Param[0]=new EncoderParameter(System.Drawing.Imaging.Encoder.Quality,(long)JpegQuality);ImageCodecInfo jpeg=null;foreach(var codec in ImageCodecInfo.GetImageEncoders())if(codec.FormatID==ImageFormat.Jpeg.Guid){jpeg=codec;break;}memory.WriteByte(1);scaled.Save(memory,jpeg,parameters);bytes+=memory.ToArray().Length;encoded++;}}}}
 clock.Stop();process.Refresh();report.AppendFormat(System.Globalization.CultureInfo.InvariantCulture,"{0},{1},{2},{3},{4},{5},{6:F1},{7:F1},{8},{9:F1},{10:F1},{11},{12},{13}\n",moving?"changing":"static",adaptive?"reuse-delta":"allocate-encode-all",width,height,frames,encoded,clock.Elapsed.TotalMilliseconds,(process.TotalProcessorTime-cpu).TotalMilliseconds,bytes,process.PrivateMemorySize64/1048576.0,process.WorkingSet64/1048576.0,GC.CollectionCount(0)-g0,GC.CollectionCount(1)-g1,GC.CollectionCount(2)-g2);if(reusable!=null)reusable.Dispose();}}
 return report.ToString();}
